const rawInput = $json.output;

// Remove ```sparql fences
let sparql = rawInput.replace(/```sparql|```/gi, '').trim();

// Ensure prefixes
const prefixes = `
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
`;

if (!sparql.toLowerCase().startsWith('prefix')) {
  sparql = prefixes.trim() + '\n\n' + sparql;
}

// Convert full datatype IRIs → xsd prefix
sparql = sparql.replace(
  /\^\^<http:\/\/www\.w3\.org\/2001\/XMLSchema#([a-zA-Z]+)>/g,
  '^^xsd:$1'
);

// Remove datatype from numeric literals
sparql = sparql.replace(
  /(\d+)\^\^xsd:integer/g,
  '$1'
);

// Remove datatype from floats
sparql = sparql.replace(
  /(\d+\.\d+)\^\^xsd:float/g,
  '$1'
);

// Remove datatype from booleans
sparql = sparql.replace(
  /(true|false)\^\^xsd:boolean/g,
  '$1'
);

// Fix quoted numbers
sparql = sparql.replace(
  /"(\d+)"\^\^xsd:integer/g,
  '$1'
);

sparql = sparql.replace(
  /"(\d+\.\d+)"\^\^xsd:float/g,
  '$1'
);

sparql = sparql.replace(
  /"(true|false)"\^\^xsd:boolean/g,
  '$1'
);

return {
  json: {
    sparqlQuery: sparql
  }
};

// Get the raw output safely
let raw = item.json.output || null;

let input;

// If raw exists, remove markdown wrappers and parse JSON
if (raw) {
  // Remove ```json ``` wrappers if present
  raw = raw.replace(/^```json\s*/i, '').replace(/```$/i, '');
  try {
    input = JSON.parse(raw);
  } catch (error) {
    input = {};
  }
} else {
  input = {};
}

// 🔧 FIX: support string OR object actor/target
const actorId =
  typeof input.actor === 'string'
    ? input.actor
    : input.actor?.id || null;

const targetId =
  typeof input.target === 'string'
    ? input.target
    : input.target?.id || null;

// Build the standardized JSON object
item.json = {
  timestamp: input.timestamp
    ? new Date(input.timestamp).toISOString()
    : new Date().toISOString(),

  actor: actorId
    ? {
        type:
          typeof input.actor === 'object'
            ? input.actor?.type || 'agent'
            : 'agent',
        id: actorId
      }
    : null,

  target: targetId
    ? {
        type:
          typeof input.target === 'object'
            ? input.target?.type || 'agent'
            : 'agent',
        id: targetId
      }
    : null,

  job: input.job || null,
  severity: input.severity || null,
  duration_ms: input.duration_ms != null ? Number(input.duration_ms) : null,

  relationships: (input.relationships || []).map(r => {
    if (typeof r === 'string') {
      const [src, rel, tgt] = r.split(' → ');
      return { source: src, type: rel, target: tgt };
    }
    return r;
  }),

  attributes: input.attributes || {},

  context_summary: input.context_summary || null,
  confidence: input.confidence != null ? Number(input.confidence) : 1.0,
  raw: raw || null,
  parseError: false
};

return item;

function expand(o) {
  if (typeof o === "string") {
    const s = o.trim();
    // If string looks like JSON
    if ((s.startsWith("{") && s.endsWith("}")) || (s.startsWith("[") && s.endsWith("]"))) {
      try {
        return expand(JSON.parse(s));
      } catch {
        return o; // fallback: leave string as-is if parse fails
      }
    }
    return o;
  }

  if (Array.isArray(o)) {
    return o.map(expand);
  }

  if (o && typeof o === "object") {
    for (const k in o) {
      // Remove raw fields entirely to avoid control character issues
      if (k === "raw") {
        delete o[k];
      } else {
        o[k] = expand(o[k]);
      }
    }
  }

  return o;
}

// ---- main logic ----
if (!$json?.output || typeof $json.output !== "string") {
  throw new Error("Expected json.output to be a string");
}

let str = $json.output
  .replace(/```json|```/gi, "") // remove markdown fences
  .trim();

// Normalize line endings
str = str.replace(/\r\n/g, "\n");

// Remove illegal JSON control characters
str = str.replace(/[\x00-\x1F]/g, "");

let obj;
try {
  obj = JSON.parse(str);
} catch (err) {
  throw new Error("Top-level JSON parse failed: " + err.message);
}

// Recursively expand all nested JSON strings
return { json: expand(obj) };

