// n8n Function Node — CPL (1) Capture Metrics (FIXED)
 // Reaches this node only when the previous Insert/HTTP succeeded.
 // Read the original telemetry from the node that emitted it, not from $json
 // (which here is a Mongo/HTTP acknowledgement, not the telemetry).

 const item = $json;

 // Try to recover the original telemetry payload from upstream nodes.
 // Order matters: pick the most recent node that carries the real data.
 let source = {};
 for (const n of [
     'Insert to Telemetry Transformation DB',
     'Graph Importer to GraphDB',
     'Telemetry Transformation Agent',
     'Extract Data for Graph DB'
 ]) {
     try {
         const upstream = $(n).item?.json;
         if (upstream && Object.keys(upstream).length > 0) { source = upstream; break; }
     } catch (e) { /* node not in execution path — keep trying */ }
 }

 // Merge: prefer source fields, fall back to current item, then null
 const get = (k) => source[k] ?? item[k] ?? null;

 let actor = null;
 let target = null;
 let message = get('message') || get('_id') || get('id') || null;
 let severity = get('severity');
 let error_code = get('error_code');
 let data_size_kb = typeof get('data_size_kb') === 'number' ? get('data_size_kb') : null;

 const now = Date.now();
 const eventTime = source.timestamp ? new Date(source.timestamp).getTime() : now;
 let latencyMs = Math.max(now - eventTime, 0);

 // Try RDF extraction from any string field on either source or item
 for (const obj of [source, item]) {
     for (const key in obj) {
         const value = obj[key];
         if (!value || typeof value !== 'string') continue;
         if (!actor) {
             const m = value.match(/hasActor>\s*<[^#]+#([^>]+)>|isActorOf>\s*<[^#]+#([^>]+)>/i);
             if (m) actor = m[1] || m[2];
         }
         if (!target) {
             const m = value.match(/hasTarget>\s*<[^#]+#([^>]+)>|isTargetOf>\s*<[^#]+#([^>]+)>/i);
             if (m) target = m[1] || m[2];
         }
         if (latencyMs === 0) {
             const m = value.match(/hasDuration(?:Ms|Milliseconds)>\s*"(\d+)"/i);
             if (m) latencyMs = parseInt(m[1]);
         }
         if (!severity) {
             const m = value.match(/hasSeverity>\s*(?:<[^#]+#([^>]+)>|"([^"]+)")/i);
             if (m) severity = m[1] || m[2];
         }
         if (!error_code) {
             const m = value.match(/hasErrorCode>\s*(?:<[^#]+#([^>]+)>|"([^"]+)")/i);
             if (m) error_code = m[1] || m[2];
         }
     }
 }

 // Fallback from context_summary if still missing
 if ((!actor || !target) && source.context_summary) {
     const m = source.context_summary.match(/Agent ['"]?([^'"]+)['"]?.*?with ['"]?([^'"\s]+)['"]?/ims);
     if (m) { actor = actor || m[1]; target = target || m[2]; }
 }

 // --- Success / failure determination ---
 // We're past the Insert/HTTP node, so by definition upstream succeeded.
// --- Success determination (always success — reaching this node means upstream OK) ---
const transformSuccess = 1;
const errorCount       = 0;
const status           = 'success';

 return {
     timestamp: eventTime,
     ingestTimestamp: now,
     totalCount: 1,
     ingestCount: 1,
     transformSuccess,
     errorCount,
     latencyMs,
     trace_id: get('trace_id'),
     job: 'context_processing_layer',
     actor: actor || 'unknown',
     target: target || 'unknown',
     region: get('region'),
     host: get('host'),
     message,
     severity,
     status,
     error_code,
     data_size_kb
 };

// Access the current input item
const item = $input.item;

// Extract the output object
const data = item.json || {};

// Use ingestTimestamp or fallback to now
const ingestTime = data.ingestTimestamp ? new Date(data.ingestTimestamp).getTime() : Date.now();

// Use event timestamp if available, else fallback to ingestTime
const eventTime = data.timestamp ? new Date(data.timestamp).getTime() : ingestTime;

// Calculate latency in ms (ingestTime - eventTime)
const latencyMs = Math.max(ingestTime - eventTime, 0); // avoid negative

// Convert timestamp to nanoseconds for Loki
const ts_ns = String(ingestTime * 1e6);

// Build the Loki push payload
const logLine = JSON.stringify({
  msg: data.message || data.id || "No message",
  ingestCount:     Number(data.ingestCount     ?? 0),
  transformSuccess: Number(data.transformSuccess ?? 0),
  totalCount:      Number(data.totalCount      ?? 0),
  errorCount:      Number(data.errorCount      ?? 0),
  latencyMs:       Number(latencyMs            ?? 0),
  status:          data.status                 ?? "unknown"
});

return {
  streams: [{
    stream: {
      job:    data.job    || "context_processing_layer",
      actor:  data.actor  || "unknown",
      target: data.target || "unknown",
      region: data.region || "unknown",
      host:   data.host   || "unknown"
    },
    values: [
      [ts_ns, logLine]
    ]
  }]
};

const input = $json;

if (!input || !input.telemetry) {
  throw new Error("Missing telemetry object");
}

const t = input.telemetry;
const attrs = t.attributes || {};

const now = Date.now();
const telemetryTime = t.timestamp ? new Date(t.timestamp).getTime() : null;

// Preserve parseError from input (default false)
const parseError = input.parseError ?? false;

// Calculate latency based on telemetry timestamp
const latencyMs =
  telemetryTime && telemetryTime <= now
    ? now - telemetryTime
    : typeof t.duration_ms === "number"
    ? t.duration_ms
    : Math.floor(Math.random() * (179000 - 68000 + 1)) + 68000; // fallback random latency

return {
  timestamp: telemetryTime ?? now,
  ingestTimestamp: now,

  totalCount: 1,
  ingestCount: 1,

  // Transform success depends only on parseError
  transformSuccess: parseError ? 0 : 1,

  // Error count only reflects parse errors
  errorCount: parseError ? 1 : 0,

  latencyMs,

  trace_id: attrs.trace_id ?? null,

  job: "context_processing_layer",

  // Actor and target are now only the type string
  actor: t.raw?.actor?.type ?? null,
  target: t.raw?.target?.type ?? null,

  region: attrs.region ?? null,
  host: null,

  message: attrs.message ?? null,
  severity: t.severity ?? null,

  // Status still reflects actual event success/failure
  status: attrs.success === true ? "success" : "failed",

  error_code: attrs.error_code ?? null,

  data_size_kb: typeof attrs.data_size_kb === "number"
    ? attrs.data_size_kb
    : null,

  parseError
};

// Access the current input item
const item = $input.item;
const data = item.json || {};

// Compute latency in milliseconds
const latencyMs =
  data.ingestTimestamp && data.timestamp
    ? data.ingestTimestamp - data.timestamp
    : 0;

const eventMs = data.ingestTimestamp ? new Date(data.ingestTimestamp).getTime() : Date.now();
const safeMs = Math.min(eventMs, Date.now());           // cap at now
const ts_ns = String(safeMs * 1e6);

// Identity-only labels (low cardinality)
const streamLabels = {
  job:          data.job    || "context_processing_layer",
  service_name: "context_processing_layer",
  actor:        data.actor  || "unknown",
  target:       data.target || "unknown",
  region:       data.region ?? "unknown",
  host:         data.host   ?? "unknown"
};

// All numerics + the original message go into the log body as JSON
const body = JSON.stringify({
  message:          data.message || "No message",
  ingestCount:      Number(data.ingestCount      ?? 0),
  transformSuccess: Number(data.transformSuccess ?? 0),
  totalCount:       Number(data.totalCount       ?? 0),
  errorCount:       Number(data.errorCount       ?? 0),
  latencyMs:        Number(latencyMs)
});

return {
  streams: [
    { stream: streamLabels, values: [[ts_ns, body]] }
  ]
};

// parse JSON-LD string
const graph = JSON.parse(items[0].json.data);

const nodeMap = new Map();
const edges = [];

graph.forEach(item => {
  const id = item["@id"];
  const types = item["@type"] || [];

  const isRelationship = types.includes(
    "http://example.org/telemetry#Relationship"
  );

  // -------------------
  // EDGES
  // -------------------
  if (isRelationship) {
    edges.push({
      id,
      source: item["http://example.org/telemetry#relationshipSource"]?.[0]?.["@id"] || "",
      target: item["http://example.org/telemetry#relationshipTarget"]?.[0]?.["@id"] || "",
      label: item["http://example.org/telemetry/inst:label"]?.[0]?.["@value"] || "",
      confidence: parseFloat(
        item["http://example.org/telemetry#hasConfidence"]?.[0]?.["@value"] || 1
      )
    });
    return; // ⛔ do NOT treat relationships as nodes
  }

  // -------------------
  // NODES (deduped)
  // -------------------
  if (!nodeMap.has(id)) {
    nodeMap.set(id, {
      id,
      type: types[0] || "",
      label:
        item["http://example.org/telemetry/inst:label"]?.[0]?.["@value"] ||
        id.replace(/^.*[#/:]/, ""),
      confidence: parseFloat(
        item["http://example.org/telemetry#hasConfidence"]?.[0]?.["@value"] || 1
      ),
      comment:
        item["http://example.org/telemetry/inst:hasComment"]?.[0]?.["@value"] || ""
    });
  }
});

return [
  {
    json: {
      nodes: Array.from(nodeMap.values()),
      edges
    }
  }
];

parameters.body:
=PREFIX ex1: <http://example.org/telemetry/inst:>
PREFIX ex: <http://example.org/telemetry#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

CONSTRUCT {
  ?node a ?type .
  ?node ex1:label ?finalLabel .
  ?node ex:hasComment ?comment .
  ?node ex:hasConfidence ?confidence .

  ?edge a ?edgeType .
  ?edge ex1:label ?edgeLabel .
  ?edge ex:hasComment ?edgeComment .
  ?edge ex:hasConfidence ?edgeConfidence .
  ?edge ex:relationshipSource ?source .
  ?edge ex:relationshipTarget ?target .
}
WHERE {
  # Nodes
  ?node rdf:type ?type .
  OPTIONAL { ?node ex1:label ?lblN }
  OPTIONAL { ?node ex:hasComment ?comment }
  OPTIONAL { ?node ex:hasConfidence ?confidence }
  BIND(COALESCE(?lblN, REPLACE(STR(?node), "^.*[#/:]", "")) AS ?finalLabel)

  # Edges
  ?edge a ?edgeType .
  OPTIONAL { ?edge ex1:label ?lblE }
  OPTIONAL { ?edge ex:hasComment ?edgeComment }
  OPTIONAL { ?edge ex:hasConfidence ?edgeConfidence }
  OPTIONAL { ?edge ex:relationshipSource ?source }
  OPTIONAL { ?edge ex:relationshipTarget ?target }
  BIND(COALESCE(?lblE, REPLACE(STR(?edge), "^.*[#/:]", "")) AS ?edgeLabel)
}
LIMIT 200

